def gc_skew(seq):
    t = len(seq)
    if t == 0: return None, None
    return (seq.count('G')-seq.count('C'))/(seq.count('G')+seq.count('C')), (seq.count('A')-seq.count('T'))/t

def seg_feats(s):
    gc = 100*(s.count('G')+s.count('C'))/len(s)
    skew, askew = gc_skew(s)
    # longest ORF scan
    def scan(ss):
        best = None
        for strand in ('+','-'):
            x = ss if strand=='+' else ss[::-1].translate(str.maketrans('ACGT','TGCA'))
            for fr in range(3):
                for m in re.finditer('ATG', x):
                    p = m.start()+fr*0
                    # generous scan
                    prot = []
                    i = p
                    stop = False
                    for i in range(p, len(x)-2, 3):
                        aa = codon_table[x[i:i+3]]
                        if aa == '*':
                            break
                        prot.append(aa)
                    else:
                        stop = True
                    L = len(prot)
                    if L >= 30:
                        if best is None or L > best[0]:
                            best = (L, strand, p+1, 'no stop' if stop else 'stop', ''.join(prot))
        return best
    return gc, skew, askew, scan(s)

