def gc_skew(s):
    t = len(s)
    return (s.count('G')-s.count('C'))/(s.count('G')+s.count('C')), (s.count('A')-s.count('T'))/t

def scan_orfs(ss, minlen=30):
    best = None
    for strand in ('+','-'):
        x = ss if strand=='+' else ss[::-1].translate(str.maketrans('ACGT','TGCA'))
        for m in re.finditer('ATG', x):
            p = m.start()
            prot = []
            for i in range(p, len(x)-2, 3):
                aa = codon_table[x[i:i+3]]
                if aa == '*':
                    break
                prot.append(aa)
            L = len(prot)
            if L >= minlen:
                if best is None or L > best[0]:
                    best = (L, strand, p+1, ''.join(prot))
    return best

L = len(seq)
w = 500; step = 250
print('win_start win_end  GC%   GCskew   ATskew   bestORF')
for st in range(0, L-w+1, step):
    s = seq[st:st+w]
    gc = 100*(s.count('G')+s.count('C'))/w
    sk, ak = gc_skew(s)
    o = scan_orfs(s)
