    header = f.readline().strip()
    seq = ''.join(l.strip() for l in f)
L=len(seq)

# Homopolymer runs (>=6)
for b in 'ACGT':
    for m in re.finditer(b+'{6,}', seq):
        s,e = m.start()+1, m.end()
        print(f'homopolymer {b}x{e-s+1}: {s}-{e} (len {e-s+1})')

# Di- and trinucleotide microsatellites
def microsats(seq, unit_len=2, min_copies=6):
    res=[]
    for i in range(len(seq)-unit_len*min_copies):
        u = seq[i:i+unit_len]
        if set(u)-set('ACGT'): continue
        j=i
        c=0
        while seq[j:j+unit_len]==u:
            c+=1; j+=unit_len
        if c>=min_copies:
            res.append((i+1, j, u, c))
    return res
seen=[]
for ms in microsats(seq,2,6):
    if all(abs(ms[0]-s0)>10 for s0 in seen):
        seen.append(ms[0]); print('di-ms:', ms)
for ms in microsats(seq,3,5):
    if all(abs(ms[0]-s0)>10 for s0 in seen):
        seen.append(ms[0]); print('tri-ms:', ms)
