import re
with open('region.fasta') as f:
    header = f.readline().strip()
    seq = ''.join(l.strip() for l in f)
L=len(seq)

def rc(s): return s[::-1].translate(str.maketrans('ACGT','TGCA'))

# ORF scan over both strands with proper enumeration of stop-free windows
codons = {}
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codons[b1+b2+b3]=aas[i]; i+=1

best=[]
for strand, x in (('+',seq), ('-', rc(seq))):
    for m in re.finditer('ATG', x):
        p=m.start()
        L_orf=0
        has_stop=False
        for k in range(p, len(x)-2, 3):
            a=codons[x[k:k+3]]
            if a=='*':
                has_stop=True
                break
            L_orf+=1
        if not has_stop:   # runs to end of sequence 5'->3' end
            # only include if long enough and not overlapping prior duplicates
            if L_orf >= 60:
                best.append((L_orf, strand, p+1, ''.join(codons[x[q:q+3]] for q in range(p, p+3*L_orf, 3))))
best.sort(reverse=True)
for L_, s_, p_, prot_ in best[:3]:
    print(f'{L_}aa {s_} start {p_}: {prot_[:60]}...')
